 sealed record SpaceRow(string Id,string Name,string Type,double Distance,float Velocity,TargetKind? Kind,bool Local);
 float solarMapZoom=1;SpacePosition solarMapFocus;
 int solarSort;bool solarDescending;bool trackingCamera;bool sensorOverlay=true;string infoSpaceId="";bool scannerWheel;
 readonly HashSet<string> hiddenSpace=[];
 IEnumerable<SpaceRow> SpaceRows(){var local=world.Targets.Where(t=>t.Alive).Select(t=>new SpaceRow(t.Id,t.Name,t.DroneId.Length>0?"Drone":t.Kind.ToString(),Vector3.Distance(t.Position,world.Player.Position),t.Velocity.Length(),t.Kind,true));var localCelestial=world.Targets.Select(t=>t.Id).ToHashSet();var remote=world.Celestials.Where(c=>c.Id!=world.SolarCelestial&&!localCelestial.Contains(c.Id)&&!(c.Kind==CelestialKind.Station&&world.Grid=="station")).Select(c=>new SpaceRow(c.Id,c.Name,c.Type,(c.Anchor-world.SystemPosition).Length,0,null,false));var signatures=world.UtilitySites.Where(s=>s.System==world.SystemId&&s.Signal>=99.99f&&s.Id!=world.SolarCelestial).Select(s=>new SpaceRow(s.Id,s.Id+" / "+s.Kind,"Resolved signature",world.WarpDistance(s.Id),0,null,false));var bookmarks=world.Bookmarks.Where(b=>b.System==world.SystemId).Select(b=>new SpaceRow(b.Id,b.Name,"Saved location",(b.Position-world.SystemPosition).Length,0,null,false));var rows=local.Concat(remote).Concat(signatures).Concat(bookmarks).Where(r=>!hiddenSpace.Contains(r.Id)&&(overviewTab==0?r.Local:overviewTab==1?r.Kind==TargetKind.Raider:overviewTab==2?r.Kind==TargetKind.Asteroid||SolarCatalog.Resolve(world.SystemId,r.Id)?.Kind is CelestialKind.AsteroidBelt or CelestialKind.IceField or CelestialKind.GasCloud:overviewTab==3?!r.Local||r.Kind is TargetKind.Station or TargetKind.Stargate or TargetKind.Wormhole or TargetKind.Celestial:true));return solarSort==1?(solarDescending?rows.OrderByDescending(r=>r.Name):rows.OrderBy(r=>r.Name)):solarSort==2?(solarDescending?rows.OrderByDescending(r=>r.Type):rows.OrderBy(r=>r.Type)):solarSort==3?(solarDescending?rows.OrderByDescending(r=>r.Velocity):rows.OrderBy(r=>r.Velocity)):(solarDescending?rows.OrderByDescending(r=>r.Distance):rows.OrderBy(r=>r.Distance));}
 SpaceRow? ChosenRow()=>SpaceRows().FirstOrDefault(r=>r.Id==world.SelectedId)??world.Celestials.Where(c=>c.Id==world.SelectedId).Select(c=>new SpaceRow(c.Id,c.Name,c.Type,(c.Anchor-world.SystemPosition).Length,0,null,false)).FirstOrDefault();
 void SolarSelected(){ui.Panel(new(1260,15,325,167),"Selected item");var r=ChosenRow();ui.Text(r==null?"No object selected":ShortSpace(r.Name,35),1273,51,White,14);ui.Text(r==null?"Choose an overview row or space bracket":SolarCatalog.Distance(r.Distance)+" / "+ShortSpace(r.Type,26),1273,74,Muted,12);
 string[] icons=[">",">|","W","O","K","+","EYE","TRK","i"];string[] tips=["Approach selected","Align to selected","Warp / dock / jump / open","Orbit selected","Keep at range","Lock / unlock target","Look at selected","Track selected","Show object information"];
 for(int i=0;i<9;i++){int index=i;ui.Button(new(1272+i*34,102,30,32),icons[i],()=>SpaceAction(index,world.SelectedId),tips[i]);}ui.Text(world.InWarp?"WARP DRIVE ACTIVE":world.Transit!=null?"Establishing warp vector":world.LockedId==world.SelectedId&&r!=null?"Target lock acquired":r?.Local==false?"Remote celestial / warp available":"Ready for command",1273,151,world.InWarp?Cyan:Muted,11);}
 static string ShortSpace(string s,int max)=>s.Length>max?s[..(max-2)]+"..":s;
 void SolarOverview(){ui.Panel(new(1260,192,325,408),"Overview");string[] tabs=["General","Targets","Mining","WarpTo","All"];for(int i=0;i<5;i++){int tab=i;ui.Button(new(1269+i*61,224,58,24),tabs[i],()=>{overviewTab=tab;overviewScroll=0;},"Overview / "+tabs[i],overviewTab==i);}
 string[] cols=["Distance","Name","Type","V m/s"];int[] xs=[1271,1349,1468,1533],widths=[75,116,62,42];for(int i=0;i<4;i++){int col=i;ui.Button(new(xs[i],253,widths[i],23),cols[i],()=>{if(solarSort==col)solarDescending=!solarDescending;else{solarSort=col;solarDescending=false;}},"Sort overview / "+cols[i]);}
 var rows=SpaceRows().ToArray();overviewScroll=Math.Clamp(overviewScroll,0,Math.Max(0,rows.Length-12));int y=281;foreach(var row in rows.Skip(overviewScroll).Take(12)){var r=row;ui.Button(new(1269,y,307,23),"",()=>world.SelectedId=r.Id,"Space object / "+r.Id,world.SelectedId==r.Id);Color c=r.Kind==TargetKind.Raider?Red:r.Kind==TargetKind.Asteroid?Gold:r.Local?White:Muted;ui.Text(SolarCatalog.Distance(r.Distance),1273,y+6,c,10);ui.Text(ShortSpace(r.Name,20),1349,y+6,c,10);ui.Text(ShortSpace(r.Type,10),1468,y+6,Muted,9);ui.Text(r.Velocity>0?r.Velocity.ToString("0"):"-",1539,y+6,Muted,10);y+=24;}
 ui.Text($"{rows.Length} objects / {overviewScroll+1}-{Math.Min(overviewScroll+12,rows.Length)}",1274,579,Muted,10);ui.Button(new(1515,572,26,21),"^",()=>overviewScroll=Math.Max(0,overviewScroll-12));ui.Button(new(1548,572,26,21),"v",()=>overviewScroll+=12);
 ui.Panel(new(1260,610,325,95),"Route / local navigation");var route=world.Route();ui.Text(route.Count>0?ShortSpace(string.Join(" > ",route.Select(id=>DemoWorld.ResolveSystem43(id).Name)),43):"No destination selected",1273,647,Muted,11);ui.Button(new(1273,670,92,25),"SYSTEM",()=>EnsureWindow(ViewMode.SolarMap),"Open solar system map");ui.Button(new(1371,670,92,25),world.ImportedWorld43?"GALAXY":"CLUSTER",()=>{if(world.ImportedWorld43)OpenGalaxy42(int.Parse(world.SystemId[7..]));else EnsureWindow(ViewMode.Map);});ui.Button(new(1469,670,101,25),"AUTO",()=>world.Autopilot=!world.Autopilot,"Toggle autopilot",world.Autopilot);}
 void SolarDroneHud(){}
 void SpaceAction(int action,string id){if(id.Length==0)return;world.SelectedId=id;var c=SolarCatalog.Resolve(world.SystemId,id);var t=world.Selected;switch(action){case 0:if(t!=null)world.SetOrder("approach");else world.Say("Approach requires an object on the local grid.");break;case 1:world.AlignTo(id);break;case 2:if(t?.Kind==TargetKind.Wormhole&&c==null){world.UseWormhole();break;}if(c?.Kind==CelestialKind.Stargate||c?.Kind==CelestialKind.Wormhole)world.UseSolarGate(id);else if(t?.Kind==TargetKind.Station)world.Dock();else if(c?.Kind==CelestialKind.Station)world.BeginWarp(id,0,"dock");else if(t?.Kind==TargetKind.Container){if(t.SiteKind is "Data" or "Relic"&&!t.Hacked)StartHack();else OpenInventoryLocationK("loot:"+id);}else if(t?.Kind==TargetKind.Wreck){OpenInventoryLocationK("loot:"+id);}else world.BeginWarp(id,world.DefaultWarpRange);break;case 3:world.SetNavigationRange("orbit",world.OrbitRange);break;case 4:world.SetNavigationRange("keep",world.KeepRange);break;case 5:if(world.RetainedLocks.Any(l=>l.Id==id)||world.LockedId==id)world.UnlockEnhancedTarget(id);else world.BeginAcquisition(id);break;case 6:if(t!=null)renderer.LookAtTarget=!renderer.LookAtTarget;else{EnsureWindow(ViewMode.SolarMap);world.Say("Remote object located on the system map.");}break;case 7:trackingCamera=!trackingCamera;if(t!=null)renderer.LookAtTarget=trackingCamera;break;case 8:ShowObjectInfo(id);break;}}
 void DrawSolarMap(){var rect=new Rectangle(207,84,1033,690);DrawWindow(rect,"Solar system map");ui.Button(new(932,737,280,25),"SYSTEM INFO",()=>ShowInformation("system/"+world.SystemId),"Solar system Show Info");ui.Text(world.Current.Name+" / scale in AU",229,125,Cyan,17);ui.Button(new(845,122,38,25),"-",()=>solarMapZoom=Math.Max(1,solarMapZoom/2));ui.Button(new(889,122,38,25),"+",()=>solarMapZoom=Math.Min(512,solarMapZoom*2));ui.Button(new(937,122,128,25),"FOCUS SELECTED",()=>{if(SolarCatalog.Resolve(world.SystemId,world.SelectedId) is {} c){solarMapFocus=c.Position;solarMapZoom=Math.Max(16,solarMapZoom);}});ui.Button(new(1072,122,144,25),"RESET VIEW",()=>{solarMapFocus=default;solarMapZoom=1;});var center=new Vector2(660,434);double max=world.Celestials.DefaultIfEmpty(new("",world.SystemId,"",CelestialKind.Beacon,default,0,"","" )).Max(c=>Math.Max(Math.Abs(c.Position.X),Math.Abs(c.Position.Z)))/SolarCatalog.AU;float scale=(float)(280/Math.Max(1,max))*solarMapZoom;Vector2 Point(SpacePosition p)=>center+new Vector2((float)((p.X-solarMapFocus.X)/SolarCatalog.AU),(float)((p.Z-solarMapFocus.Z)/SolarCatalog.AU))*scale;
 foreach(var c in world.Celestials.Where(c=>c.Kind==CelestialKind.Planet)){ui.Circle(Point(default),(float)(c.Position.Length/SolarCatalog.AU)*scale,new Color(40,63,73),1);}
 foreach(var sun in world.Celestials.Where(c=>c.Kind==CelestialKind.Sun)){var star=Point(sun.Position);ui.Circle(star,7,Gold,4);ui.Text("Primary star",star.X+12,star.Y,Gold,12);string sid=sun.Id;ui.Hits.Add(new(new((int)star.X-9,(int)star.Y-9,18,18),()=>world.SelectedId=sid,"Space object / "+sid));}foreach(var c in world.Celestials.Where(c=>c.Kind is CelestialKind.Planet or CelestialKind.Stargate or CelestialKind.Station or CelestialKind.Wormhole or CelestialKind.Beacon||solarMapZoom>=8&&c.Kind is CelestialKind.Moon or CelestialKind.AsteroidBelt or CelestialKind.IceField or CelestialKind.GasCloud)){var at=Point(c.Position);if(at.X is <220 or >1220||at.Y is <170 or >700)continue;ui.Circle(at,c.Kind==CelestialKind.Planet?5:3,c.Kind==CelestialKind.Stargate?Green:Cyan,2);ui.Text(ShortSpace(c.Name,28),at.X+8,at.Y-5,Muted,10);string id=c.Id;ui.Hits.Add(new(new((int)at.X-9,(int)at.Y-9,18,18),()=>world.SelectedId=id,"Space object / "+id));}var player=Point(world.SystemPosition);ui.Hex(player,10,White);ui.Text("Your ship",player.X+12,player.Y+9,White,12);ui.Text($"{max/solarMapZoom:0.000} AU half-width / 8,000 km local grids",230,713,Muted,12);ui.Button(new(230,737,220,25),"WARP TO SELECTED",()=>world.BeginWarp(world.SelectedId,world.DefaultWarpRange));ui.Button(new(464,737,220,25),"SAVE LOCATION",()=>world.AddBookmark());ui.Button(new(698,737,220,25),"ALIGN TO SELECTED",()=>world.AlignTo(world.SelectedId));}
 IEnumerable<Celestial> BracketCelestials()=>world.Celestials.Where(c=>c.Id!=world.SolarCelestial&&!hiddenSpace.Contains(c.Id)&&ShowBracketK(c)&&(c.Id==world.SelectedId||sensorOverlay&&c.Kind is CelestialKind.Planet or CelestialKind.Stargate or CelestialKind.Station or CelestialKind.Anomaly or CelestialKind.Wormhole));
 Vector3 CelestialScreen(Celestial c){var delta=c.Position-world.SystemPosition-SpacePosition.From(renderer.CameraPosition-world.Player.Position);return renderer.Project(renderer.CameraPosition+delta.Unit.Local*70000);}
 void SolarBrackets(){if(world.InWarp)return;foreach(var c in BracketCelestials()){var p=CelestialScreen(c);if(p.Z is <0 or >1||p.X is <416 or >1235||p.Y is <15 or >650)continue;var at=new Vector2(p.X,p.Y);bool selected=world.SelectedId==c.Id;ui.Hex(at,selected?9:5,selected?Cyan:new Color(97,132,150,150));if(selected||Vector2.Distance(at,mouse)<25){ui.Text(c.Name,p.X+15,p.Y-10,selected?White:Muted,11);ui.Text(SolarCatalog.Distance((c.Anchor-world.SystemPosition).Length),p.X+15,p.Y+7,Muted,10);}}}
 void DrawSolarEffects(){if(world.Docked||world.Transit==null)return;var trip=world.Transit;bool flight=world.InWarp;if(flight){float f=(float)Math.Clamp(trip.Curve.Sample(trip.Elapsed).Velocity/trip.Curve.Peak,0,1);for(int i=0;i<46;i++){float a=i*MathF.Tau/46+time*.015f;var d=new Vector2(MathF.Cos(a),MathF.Sin(a));float offset=(time*170+i*29)%120;ui.Line(new Vector2(785,419)+d*(100+offset),new Vector2(785,419)+d*(190+offset+330*f),new Color(83,151,191,(int)(30+80*f)),1+i%2);}ui.Center("WARP DRIVE ACTIVE",790,582,Cyan,18);var sample=trip.Curve.Sample(trip.Elapsed);ui.Center($"{trip.Phase.ToUpper()} / {sample.Velocity/SolarCatalog.AU:0.00} AU/s",790,608,White,13);ui.Center($"{SolarCatalog.Distance(trip.Curve.Distance-sample.Distance)} remaining / {trip.Curve.Total-trip.Elapsed:0.0} s",790,629,Muted,12);}else{ui.Center("ESTABLISHING WARP VECTOR",790,582,Cyan,17);ui.Center($"{world.Player.Velocity.Length()/Math.Max(1,world.Player.Speed):P0} speed / 75% required",790,608,Muted,12);}}
